    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # Helper function to check if a permutation is special
        def is_special(perm):
            for i in range(n - 1):
                if perm[i] % perm[i + 1] != 0 and perm[i + 1] % perm[i] != 0:
                    return False
            return True

        # Recursive function to count special permutations
        @lru_cache(None)
        def count_permutations(i, mask):
            if mask == (1 << n) - 1:
                return 1

            count = 0
            for j in range(n):
                if mask & (1 << j) == 0 and (i == -1 or nums[j] % nums[i] == 0 or nums[i] % nums[j] == 0):
                    count += count_permutations(j, mask | (1 << j))
                    count %= MOD

            return count

        return count_permutations(-1, 0)
