    def get_possible_positions(start_row, start_col, N, T):
        positions = set()
        queue = [(start_row, start_col)]

        for _ in range(N):
            new_queue = []
            for x, y in queue:
                for dx, dy in directions.values():
                    nx, ny = x + dx, y + dy
                    if is_valid(nx, ny):
                        new_queue.append((nx, ny))
                        positions.add((nx, ny))
            queue = new_queue

        return positions

    # Get all possible positions after N moves
    possible_positions = get_possible_positions(start_row, start_col, N, T)

    # Count the number of unique positions
    return len(possible_positions)

